const seenTitles = new Set();
const filteredNews = [];
const noiseKeywords = ['[포토]', '그래픽', '인사', '부고', '게시판', '환율', '특징주 SUMMARY', '메모'];

// 1. n8n 인풋 배열에서 네이버 raw 아이템 목록을 강제로 추출하는 로직
let rawItems = [];

const allInputs = $input.all();
if (allInputs && allInputs.length > 0) {
    // 상황 A: 이전 노드에서 이미 items 배열을 스플릿하여 여러 개로 넘겨준 경우
    if (allInputs.length > 1) {
        rawItems = allInputs.map(item => item.json);
    } else {
        // 상황 B: 하나의 거대한 json 객체 안에 items 배열이 들어있는 경우
        const firstJson = allInputs[0].json;
        if (firstJson.items && Array.isArray(firstJson.items)) {
            rawItems = firstJson.items;
        } else if (Array.isArray(firstJson)) {
            rawItems = firstJson;
        } else {
            // 상황 C: 단일 아이템만 들어온 경우
            rawItems = [firstJson];
        }
    }
}

// 2. 루프를 돌며 정밀 필터링 및 데이터 정제
for (const rawData of rawItems) {
    if (!rawData) continue;

    const title = rawData.title || '';
    const desc = rawData.description || rawData.desc || '';
    const originallink = rawData.originallink || rawData.link || '';
    const pubDateKST = rawData.pubDateKST || rawData.pubDate || rawData.pub_date_kst || '';

    if (!title && !desc) continue;

    // 광고 및 노이즈 키워드 필터링
    if (noiseKeywords.some(keyword => title.includes(keyword))) continue;

    // 중복 제거 (앞 글자 15자 자르고 공백 제거)
    const simplifiedTitle = title.substring(0, 15).replace(/\s+/g, '');
    if (seenTitles.has(simplifiedTitle)) continue;

    seenTitles.add(simplifiedTitle);
    filteredNews.push({
        title: title,
        description: desc,
        originallink: originallink,
        pubDateKST: pubDateKST
    });
}

// 만약 필터링 후 남은 뉴스가 하나도 없다면 더미 데이터 반환하여 에러 방출 차단
if (filteredNews.length === 0) {
    return [{ json: { news_chunk: [{ title: "수집된 뉴스 없음", description: "당일 유효 데이터 부재", originallink: "", pubDateKST: "" }] } }];
}

// 3. 10개씩 청크(Chunk) 배열로 패키징
const chunkSize = 10;
const chunks = [];
for (let i = 0; i < filteredNews.length; i += chunkSize) {
    chunks.push({
        json: {
            news_chunk: filteredNews.slice(i, i + chunkSize)
        }
    });
}

return chunks;

const items = $input.all();
const splitResults = [];

// 1번째 전처리 Code 노드의 n8n 이름을 적어줍니다. 기본 이름이 'Code'일 경우 그대로 둡니다.
const originalNodeItems = $('Code in JavaScript').all(); 

items.forEach((item, chunkIndex) => {
    try {
        let rawText = item.json.content?.parts?.[0]?.text;
        if (!rawText) return;

        // 문자열 정제 후 JSON 객체 배열로 변환
        rawText = rawText.replace(/```json|```/g, '').trim();
        const aiEvaluations = JSON.parse(rawText); 

        // 1번째 노드에 잠들어 있던 매칭되는 원본 뉴스 청크 상자 강제 소환
        const originalChunk = originalNodeItems[chunkIndex]?.json?.news_chunk || [];

        // 인덱스 기준으로 원본 뉴스의 메타데이터와 AI 점수를 1:1로 한 몸으로 결합
        aiEvaluations.forEach((evalItem, newsIndex) => {
            const originalNews = originalChunk[newsIndex] || {};

            splitResults.push({
                json: {
                    title: originalNews.title ? originalNews.title.replace(/<b>|<\/b>|&quot;|&amp;/g, '') : '', // HTML 태그 및 특수문자 정제
                    description: originalNews.description ? originalNews.description.replace(/<b>|<\/b>|&quot;|&amp;/g, '') : '',
                    originallink: originalNews.originallink || '',
                    pubDateKST: originalNews.pubDateKST || '',
                    sentiment_score: evalItem.sentiment_score,
                    market_scenario: evalItem.market_scenario
                }
            });
        });
    } catch (e) {
        return;
    }
});

return splitResults;

